// TH15 Stage 5 道中 第9波：GirlD04 左右交替 6 只（st05.ecl.txt MainSub08 1627-1665）
// 依赖 GirlD04 / GirlD04_at / GirlD04_at2（st05.ecl.txt 1149-1224）。
// 源 type16 / color6 → TH15_STAR_R；炮序、角增量、I0/I1 与 VELTIME 目标速按 rank 还原。

const TIME_LIMIT: int = 1324;   // 段计时：120 开场 + 1200 攻击窗 + 4 启动余量
const OPENING_BUFFER: int = 120;

const TH15_STAR_R: int = 608;
const BULLET_COLOR: int = 6;

const SWEEP_FRAMES: int = 3000; // 源 at2 $C=3000 逐帧循环
const RAMP_FRAMES: int = 120;   // 源 VELTIME 0x200000 a=120

// 源 at2 的 EX：ANIM 出生动画按公共口径省略；VELTIME(a=120, r=6/8/10/8, s=-999999 保留角)
// 即沿出生角每帧加 delta 到目标标量速，用沿向加速度表达，120 帧后停。
xformdef SPEED_RAMP(accel: fx) {
    @120 set_accel(accel);
    set_accel(0fx);
}

// 源 GirlD04_at2（1179-1224）：etAim(0,1) 固定方向扇形；每帧 etOn 一发，
// B< I0 或 B>=I1 时发射，基准角 A 每帧 +delta。每发 count 路、层 1。
async sub girl_fire(base: angle, delta: angle, i0: int, i1: int, cnt: int, accel: fx) {
    sh_reset(0);
    sh_sprite(0, TH15_STAR_R, BULLET_COLOR);
    sh_aim(0, 0);          // etAim(0,1) = 固定方向
    sh_ring(0, 0);         // fan，路间距 = etAngle 第二参 45°
    sh_count(0, cnt, 1);   // etCount(0, count, 1)
    sh_speed(0, 0fx, 0fx); // etSpeed(0,0,1)：单层初速 0，交给 SPEED_RAMP
    sh_xform(0, SPEED_RAMP(accel));
    var a: angle = base;
    for j in 0..SWEEP_FRAMES {
        if j < i0 || j >= i1 {
            sh_angle(0, a, 45deg);   // 源 etAngle(0, A, 0.7853982)
            sh_fire(0);
        }
        a = a + delta;   // 源 %A = %A + %F1
        wait(1);
    }
}

// 源 GirlD04_at（1162-1177）：框、极坐标运动、并行 at2、wait(40) 后二次转向。
// 父镜像(0x80000)作用于移动：右敌的 78.75°/-11.25° 关于竖轴镜像（101.25°/191.25°）；
// 发射角由源自行镜像（135° / -delta），不再套移动镜像。
async sub girl(base: angle, delta: angle, i0: int, i1: int, cnt: int, accel: fx,
               ma: angle, mb: angle) {
    set_invuln(65535);
    set_hurtbox(12fx);   // 源 setHurtbox(24,24)，普通圆半径 24*0.5
    set_hitbox(8fx);     // 源 setHitbox(16,16)，普通圆半径 16*0.5
    move_vel(0, 16384bam, 3fx, EASE_LINEAR);   // 源 moveVel(1.5707964, 3.0)
    move_vel(60, ma, 0fx, EASE_QUAD_IN);       // 源 moveVelTime(60, mode1, 1.3744467, 0.0)
    spawn girl_fire(base, delta, i0, i1, cnt, accel);
    wait(40);
    move_vel(60, mb, 4fx, EASE_LINEAR);        // 源 moveVelTime(60, mode0, -0.19634955, 4.0)
    loop { wait(1); }
}

// MainSub08 的单只创建：x 相对父(0,0)，side=0 左 / 1 右（enmCreateM 镜像）。
sub emit_girl(base: angle, delta: angle, i0: int, i1: int, cnt: int, accel: fx, side: int) {
    var x: fx = -192fx;
    var ma: angle = 14336bam;   // 78.75°
    var mb: angle = -2048bam;   // -11.25°
    if side != 0 {
        x = 192fx;
        ma = 18432bam;          // 101.25°：移动关于竖轴镜像
        mb = 34816bam;          // 191.25°
    }
    _ = spawn_enemy(x, -48fx, 1000, 0, 0, 0,
                    girl(base, delta, i0, i1, cnt, accel, ma, mb));
}

// MainSub08（1629-1665）：wait(80)，随后 6 次创建，间隔 wait(60)，末尾 wait(120)。
async sub wave() {
    wait(OPENING_BUFFER);
    var rank: int = global(GVAR_RANK);
    var cnt: int = 2;                    // !E/!N/!H = 2
    if rank == RANK_LUNATIC { cnt = 3; } // !LO = 3
    var spd: fx = 8fx;                   // !N / !LO = 8
    if rank == RANK_EASY { spd = 6fx; }  // !E = 6
    if rank == RANK_HARD { spd = 10fx; } // !H = 10
    var accel: fx = spd / RAMP_FRAMES;
    var i1a: int = 30;   // pair1 diffI(60,30,25,30)
    if rank == RANK_EASY { i1a = 60; }
    if rank == RANK_HARD { i1a = 25; }
    var i1b: int = 20;   // pair2 diffI(60,20,18,20)
    if rank == RANK_EASY { i1b = 60; }
    if rank == RANK_HARD { i1b = 18; }
    var i1c: int = 29;   // pair3 diffI(60,29,29,29)
    if rank == RANK_EASY { i1c = 60; }

    wait(80);
    emit_girl(8192bam, 146bam, 20, i1a, cnt, accel, 0);     // %F0=0.785398, %F1=+0.013963
    wait(60);
    emit_girl(24576bam, -146bam, 20, i1a, cnt, accel, 1);   // %F0=2.356194, %F1=-0.013963
    wait(60);
    emit_girl(8192bam, 146bam, 15, i1b, cnt, accel, 0);
    wait(60);
    emit_girl(24576bam, -146bam, 15, i1b, cnt, accel, 1);
    wait(60);
    emit_girl(8192bam, 146bam, 25, i1c, cnt, accel, 0);
    wait(60);
    emit_girl(24576bam, -146bam, 25, i1c, cnt, accel, 1);
    wait(120);
    loop { wait(1); }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
